import { createInvoice, issueInvoice, invoiceTotals } from './src/invoices.js';
import { recordPayment } from './src/payments.js';
import { statement } from './src/statements.js';

// Create two invoices for C-001
const inv1 = createInvoice({
  customerId: 'C-001',
  issueDate: '2025-10-07',
  lines: [{ sku: 'LOGO-PACK', qty: 1 }],
});

const inv2 = createInvoice({
  customerId: 'C-001',
  issueDate: '2025-10-10',
  lines: [{ sku: 'BRAND-BOOK', qty: 1 }],
});

// Issue both
let issued1 = issueInvoice(inv1.value, []).value;
let issued2 = issueInvoice(inv2.value, ['INV-2025-0001']).value;

const totals1 = invoiceTotals(issued1);
const totals2 = invoiceTotals(issued2);

// Pay first invoice partially, leave second unpaid
issued1 = recordPayment(issued1, {
  amount: Math.floor(totals1.total / 2),
  date: '2025-10-08',
}).value;

// Generate statement
const stmt = statement('C-001', [issued1, issued2], '2025-10-31');

console.log('Customer Statement for C-001 (as of 2025-10-31):\\n');
console.log('Number       Issue Date   Due Date     Total      Due');
console.log('─'.repeat(55));
