  const num = inv.number.padEnd(12);
  const issue = inv.issueDate.padEnd(12);
  const due = inv.dueDate.padEnd(12);
  const total = ('€' + (inv.total/100).toFixed(2)).padStart(10);
  const owing = ('€' + (inv.due/100).toFixed(2)).padStart(10);
  console.log(\`\${num}\${issue}\${due}\${total}  \${owing}\`);
}
console.log('─'.repeat(55));
console.log('Total Due: €' + (stmt.value.totalDue/100).toFixed(2));
